package com.labbaslabs.jampsfit.database

import org.json.JSONObject

private fun JSONObject.putNullable(key: String, value: Int?): JSONObject = if (value == null) put(key, JSONObject.NULL) else put(key, value)
private fun JSONObject.intOrNull(key: String): Int? = if (isNull(key)) null else optInt(key)

fun HealthEntry.toJson() = JSONObject().put("timestamp", timestamp).putNullable("battery", battery).putNullable("heartRate", heartRate).putNullable("spo2", spo2).putNullable("systolic", systolic).putNullable("diastolic", diastolic).putNullable("steps", steps).putNullable("activityCount", activityCount).putNullable("distance", distance).putNullable("calories", calories).putNullable("sleepMinutes", sleepMinutes).putNullable("deepSleepMinutes", deepSleepMinutes).putNullable("lightSleepMinutes", lightSleepMinutes).put("sleepSegmentsJson", sleepSegmentsJson)
fun JSONObject.toHealthEntry() = HealthEntry(timestamp = optLong("timestamp"), battery = intOrNull("battery"), heartRate = intOrNull("heartRate"), spo2 = intOrNull("spo2"), systolic = intOrNull("systolic"), diastolic = intOrNull("diastolic"), steps = intOrNull("steps"), activityCount = intOrNull("activityCount"), distance = intOrNull("distance"), calories = intOrNull("calories"), sleepMinutes = intOrNull("sleepMinutes"), deepSleepMinutes = intOrNull("deepSleepMinutes"), lightSleepMinutes = intOrNull("lightSleepMinutes"), sleepSegmentsJson = optString("sleepSegmentsJson").takeIf { it != "null" })

fun FoodEntity.toJson() = JSONObject().put("name", name).put("source", source).put("role", role).put("unitLabel", unitLabel).put("kcalPerUnit", kcalPerUnit).put("defaultAmount", defaultAmount).put("stepSize", stepSize).put("enabled", enabled).put("availableAmount", availableAmount).put("isCustom", isCustom).put("onShoppingList", onShoppingList)
fun JSONObject.toFood() = FoodEntity(name = optString("name"), source = optString("source"), role = optString("role"), unitLabel = optString("unitLabel"), kcalPerUnit = optInt("kcalPerUnit"), defaultAmount = optDouble("defaultAmount").toFloat(), stepSize = optDouble("stepSize").toFloat(), enabled = optBoolean("enabled", true), availableAmount = if (isNull("availableAmount")) null else optDouble("availableAmount").toFloat(), isCustom = optBoolean("isCustom"), onShoppingList = optBoolean("onShoppingList"))

fun FestivalEntity.toJson() = JSONObject().put("name", name).put("imageUri", imageUri).put("isActive", isActive).put("createdAt", createdAt).put("updatedAt", updatedAt)
fun JSONObject.toFestival() = FestivalEntity(name = optString("name", DEFAULT_FESTIVAL_NAME), imageUri = optString("imageUri").takeIf { it != "null" }, isActive = optBoolean("isActive"), createdAt = optLong("createdAt"), updatedAt = optLong("updatedAt"))

fun EventEntity.toJson() = JSONObject().put("festivalId", festivalId).put("type", type).put("name", name).put("startTime", startTime).put("endTime", endTime).put("startSteps", startSteps).put("startActivityCount", startActivityCount).put("startDistance", startDistance).put("startCalories", startCalories).put("durationSeconds", durationSeconds).put("stepDelta", stepDelta).put("activityDelta", activityDelta).put("distanceDelta", distanceDelta).put("calorieDelta", calorieDelta).put("heartRateSamples", heartRateSamples).put("averageBpm", averageBpm).put("minBpm", minBpm).put("maxBpm", maxBpm).put("estimatedWorkoutCalories", estimatedWorkoutCalories).put("lastUpdatedTime", lastUpdatedTime)
