fun SupplementEntity.toJson() = JSONObject().put("name", name).put("dailyTargetMg", dailyTargetMg).put("singleDoseMg", singleDoseMg).put("selectedAmountMg", selectedAmountMg).put("stepMg", stepMg).put("maxDailyMg", maxDailyMg).put("sortOrder", sortOrder).put("rampEnabled", rampEnabled).put("rampStartMg", rampStartMg).put("rampTargetMg", rampTargetMg).put("rampDays", rampDays).put("rampStartedAt", rampStartedAt).put("updatedAt", updatedAt)
